    /// </summary>
    public static class NPPNativeMethods_Ctx
    {
        internal const string NPPC_API_DLL_NAME = NPPNativeMethods.NPPC_API_DLL_NAME;
        internal const string NPPIAL_API_DLL_NAME = NPPNativeMethods.NPPIAL_API_DLL_NAME;
        internal const string NPPICC_API_DLL_NAME = NPPNativeMethods.NPPICC_API_DLL_NAME;
        internal const string NPPIDEI_API_DLL_NAME = NPPNativeMethods.NPPIDEI_API_DLL_NAME;
        internal const string NPPIF_API_DLL_NAME = NPPNativeMethods.NPPIF_API_DLL_NAME;
