                /// </returns>
                [DllImport(NPPIDEI_API_DLL_NAME, CallingConvention = CallingConvention.Cdecl)]
                public static extern NppStatus nppiSet_8s_C3R_Ctx([In, MarshalAs(UnmanagedType.LPArray, SizeConst = 3)] sbyte[] aValue, CUdeviceptr pDst, int nDstStep, NppiSize oSizeROI, NppStreamContext nppStreamCtx);


