                /// </returns>
                [DllImport(NPPIDEI_API_DLL_NAME, CallingConvention = CallingConvention.Cdecl)]
                public static extern NppStatus nppiSet_8u_C4R_Ctx([In, MarshalAs(UnmanagedType.LPArray, SizeConst = 4)] byte[] aValues, CUdeviceptr pDst, int nDstStep, NppiSize oSizeROI, NppStreamContext nppStreamCtx);


                /// <summary>
                /// Masked 4 channel 8-bit unsigned image set.
                /// </summary>
                /// <param name="aValues">Four-channel array containing the pixel-value to be set.</param>
                /// <param name="pDst">Destination-Image Pointer.</param>
