                public static extern NppStatus nppiSet_8u_AC4R_Ctx([In, MarshalAs(UnmanagedType.LPArray, SizeConst = 3)] byte[] aValues, CUdeviceptr pDst, int nDstStep, NppiSize oSizeROI, NppStreamContext nppStreamCtx);


                /// <summary>
