                public static extern NppStatus nppiSet_16u_C4MR_Ctx([In, MarshalAs(UnmanagedType.LPArray, SizeConst = 4)] ushort[] aValues, CUdeviceptr pDst, int nDstStep, NppiSize oSizeROI, CUdeviceptr pMask, int nMaskStep, NppStreamContext nppStreamCtx);


                /// <summary>
