                /// <see cref="nppiWarpAffine_8u_C1R_Ctx"/>
                /// </summary>
                [DllImport(NPPIG_API_DLL_NAME, CallingConvention = CallingConvention.Cdecl)]
                public static extern NppStatus nppiWarpAffine_8u_C4R_Ctx(CUdeviceptr pSrc, NppiSize oSrcSize, int nSrcStep, NppiRect srcRoi, CUdeviceptr pDst, int nDstStep, NppiRect dstRoi, [In, MarshalAs(UnmanagedType.LPArray, SizeConst = 6)] double[,] coeffs, InterpolationMode eInterpolation, NppStreamContext nppStreamCtx);


                /// <summary>
                /// Affine transform of an image (8bit unsigned integer, four channels RGBA).
                /// <see cref="nppiWarpAffine_8u_C1R_Ctx"/>
                /// </summary>
                [DllImport(NPPIG_API_DLL_NAME, CallingConvention = CallingConvention.Cdecl)]
                public static extern NppStatus nppiWarpAffine_8u_AC4R_Ctx(CUdeviceptr pSrc, NppiSize oSrcSize, int nSrcStep, NppiRect srcRoi, CUdeviceptr pDst, int nDstStep, NppiRect dstRoi, [In, MarshalAs(UnmanagedType.LPArray, SizeConst = 6)] double[,] coeffs, InterpolationMode eInterpolation, NppStreamContext nppStreamCtx);


                /// <summary>
                /// Affine transform of an image (8bit unsigned integer, three planes).
                /// <see cref="nppiWarpAffine_8u_C1R_Ctx"/>
                /// </summary>
                [DllImport(NPPIG_API_DLL_NAME, CallingConvention = CallingConvention.Cdecl)]
                public static extern NppStatus nppiWarpAffine_8u_P3R_Ctx([In, MarshalAs(UnmanagedType.LPArray, SizeConst = 3)] CUdeviceptr[] pSrc, NppiSize oSrcSize, int nSrcStep, NppiRect srcRoi, [In, MarshalAs(UnmanagedType.LPArray, SizeConst = 3)] CUdeviceptr[] pDst, int nDstStep, NppiRect dstRoi, [In, MarshalAs(UnmanagedType.LPArray, SizeConst = 6)] double[,] coeffs, InterpolationMode eInterpolation, NppStreamContext nppStreamCtx);


                /// <summary>
                /// Affine transform of an image (8bit unsigned integer, four planes).
                /// <see cref="nppiWarpAffine_8u_C1R_Ctx"/>
