                /// <summary>
                /// Perspective transform of an image (8bit unsigned integer, four channels RGBA).
                /// <see cref="nppiWarpPerspective_8u_C1R_Ctx"/>
                /// </summary>
                [DllImport(NPPIG_API_DLL_NAME, CallingConvention = CallingConvention.Cdecl)]
                public static extern NppStatus nppiWarpPerspective_8u_AC4R_Ctx(CUdeviceptr pSrc, NppiSize oSrcSize, int nSrcStep, NppiRect srcRoi, CUdeviceptr pDst, int nDstStep, NppiRect dstRoi, [In, MarshalAs(UnmanagedType.LPArray, SizeConst = 9)] double[,] coeffs, InterpolationMode eInterpolation, NppStreamContext nppStreamCtx);


                /// <summary>
                /// Perspective transform of an image (8bit unsigned integer, three planes).
                /// <see cref="nppiWarpPerspective_8u_C1R_Ctx"/>
                /// </summary>
                [DllImport(NPPIG_API_DLL_NAME, CallingConvention = CallingConvention.Cdecl)]
