            /// <summary>
            /// Primitives for computing the average error between two images.<para/>
            /// Given two images Src1 and Src2 both with width W and height H.<para/>
            /// If the image is in complex format, the absolute value is used for computation.
            /// </summary>
            public static class AverageError
            {
#if (NETCOREAPP)
                static AverageError()
                {
                    NPPNativeMethods.Init();
                }
#endif
                /// <summary>
