                public static extern NppStatus nppiAverageError_8u_C1R_Ctx(CUdeviceptr pSrc1, int nSrc1Step, CUdeviceptr pSrc2, int nSrc2Step, NppiSize oSizeROI, CUdeviceptr pError, CUdeviceptr pDeviceBuffer, NppStreamContext nppStreamCtx);


                /// <summary>
                /// One-channel 8-bit signed image Average_Error.
                /// </summary>
                /// <param name="pSrc1">Source-Image Pointer.</param>
                /// <param name="nSrc1Step">Source-Image Line Step.</param>
                /// <param name="pSrc2">Source-Image Pointer.</param>
