                /// Single channel 8-bit unsigned threshold adaptive box filter with border control.
                /// </summary>
                /// <param name="pSrc">Source-Image Pointer.</param>
                /// <param name="nSrcStep">Source-Image Line Step.</param>
                /// <param name="oSrcSize">Source image width and height in pixels relative to pSrc.</param>
                /// <param name="oSrcOffset">The pixel offset that pSrc points to relative to the origin of the source image. </param>
                /// <param name="pDst">Destination-Image Pointer.</param>
                /// <param name="nDstStep">Destination-Image Line Step.</param>
                /// <param name="oSizeROI">Region-of-Interest (ROI).</param>
                /// <param name="oMaskSize">Width and Height of the neighborhood region for the local</param>
                /// <param name="nDelta">Neighborhood average adjustment value</param>
                /// <param name="nValGT">Destination output value if source pixel is greater than average.</param>
                /// <param name="nValLE">Destination output value if source pixel is less than or equal to average.</param>
                /// <param name="eBorderType">The border type operation to be applied at source image border boundaries.</param>
                /// <param name="nppStreamCtx">NPP stream context.</param>
                [DllImport(NPPIF_API_DLL_NAME, CallingConvention = CallingConvention.Cdecl)]
                public static extern NppStatus nppiFilterThresholdAdaptiveBoxBorder_8u_C1R_Ctx(CUdeviceptr pSrc, int nSrcStep, NppiSize oSrcSize, NppiPoint oSrcOffset, CUdeviceptr pDst, int nDstStep, NppiSize oSizeROI, NppiSize oMaskSize, float nDelta, byte nValGT, byte nValLE, NppiBorderType eBorderType, NppStreamContext nppStreamCtx);


            }

