                /// <param name="nppStreamCtx">NPP stream context.</param>
                [DllImport(NPPIF_API_DLL_NAME, CallingConvention = CallingConvention.Cdecl)]
                public static extern NppStatus nppiFilterHoughLine_8u32f_C1R_Ctx(CUdeviceptr pSrc, int nSrcStep, NppiSize oSizeROI, NppPointPolar nDelta, int nThreshold, CUdeviceptr pDeviceLines, int nMaxLineCount, CUdeviceptr pDeviceLineCount, CUdeviceptr pDeviceBuffer, NppStreamContext nppStreamCtx);

