            /// <summary>
            /// Primitives for computing the image quality between two images, such as MSE, PSNR, SSIM, and MS-SSIM.
            /// </summary>
            public static class IQA
            {
#if (NETCOREAPP)
                static IQA()
                {
                    NPPNativeMethods.Init();
                }
#endif
                /// <summary>
                /// One-channel 8-bit unsigned image MSE.
                /// </summary>
                /// <param name="pSrc1">Source-Image Pointer.</param>
                /// <param name="nSrc1Step">Source-Image Line Step.</param>
                /// <param name="pSrc2">Source-Image Pointer.</param>
                /// <param name="nSrc2Step">Source-Image Line Step.</param>
                /// <param name="oSizeROI">Region-of-Interest (ROI).</param>
                /// <param name="pMSE">Pointer to the computed MSE of two images. </param>
                /// <param name="pDeviceBuffer">Pointer to the required device memory allocation, Scratch Buffer and Host Pointer. </param>
                /// <param name="nppStreamCtx">NPP stream context.</param>
                [DllImport(NPPIST_API_DLL_NAME, CallingConvention = CallingConvention.Cdecl)]
                public static extern NppStatus nppiMSE_8u_C1R_Ctx(CUdeviceptr pSrc1, int nSrc1Step, CUdeviceptr pSrc2, int nSrc2Step, NppiSize oSizeROI, CUdeviceptr pMSE, CUdeviceptr pDeviceBuffer, NppStreamContext nppStreamCtx);


                /// <summary>
                /// Three-channel 8-bit unsigned image MSE.
