            /// <summary>
            /// radial profile based upon a specified center point.
            /// </summary>
            public static class Profiles
            {
#if (NETCOREAPP)
                static Profiles()
                {
                    NPPNativeMethods.Init();
                }
#endif
                /// <summary>
                /// One-channel 8-bit unsigned image MSE.
                /// </summary>
                /// <param name="pSrc1">Source-Image Pointer.</param>
                /// <param name="nSrc1Step">Source-Image Line Step.</param>
                /// <param name="pSrc2">Source-Image Pointer.</param>
                /// <param name="nSrc2Step">Source-Image Line Step.</param>
                /// <param name="oSizeROI">Region-of-Interest (ROI).</param>
                /// <param name="pMSE">Pointer to the computed MSE of two images. </param>
                /// <param name="pDeviceBuffer">Pointer to the required device memory allocation, Scratch Buffer and Host Pointer. </param>
                /// <param name="nppStreamCtx">NPP stream context.</param>
                [DllImport(NPPIST_API_DLL_NAME, CallingConvention = CallingConvention.Cdecl)]
                public static extern NppStatus nppiMSE_8u_C1R_Ctx(CUdeviceptr pSrc1, int nSrc1Step, CUdeviceptr pSrc2, int nSrc2Step, NppiSize oSizeROI, CUdeviceptr pMSE, CUdeviceptr pDeviceBuffer, NppStreamContext nppStreamCtx);


                /// <summary>
                /// One-channel 32-bit Circular radial profile based upon a specified center point.
                /// </summary>
                /// <param name="pSrc">Source-Image Pointer.</param>
                /// <param name="nSrcStep">Source-Image Line Step.</param>
                /// <param name="oSizeROI">Region-of-Interest (ROI).</param>
                /// <param name="oCenter">center of circle that radial profile is computed from.  Center does not have to be on the image.</param>
                /// <param name="pProfileData">pointer to output NppiProfileData array containing count, mean, and std_dev as a function of radius.</param>
                /// <param name="nProfileSamples">number of radii to be sampled: from 0 through nProfileSamples-1.</param>
                /// <param name="nppStreamCtx">NPP stream context.</param>
                /// <returns></returns>
                [DllImport(NPPIST_API_DLL_NAME, CallingConvention = CallingConvention.Cdecl)]
                public static extern NppStatus nppiCircularRadialProfile_32f_C1R_Ctx(CUdeviceptr pSrc, int nSrcStep, NppiSize oSizeROI, NppiPoint32f oCenter,
                     CUdeviceptr pProfileData, ushort nProfileSamples, NppStreamContext nppStreamCtx);


                /// <summary>
                /// One-channel 32-bit Elliptical radial profile based upon a specified center point, angle, and astigmatism.
                /// </summary>
                /// <param name="pSrc">Source-Image Pointer.</param>
                /// <param name="nSrcStep">Source-Image Line Step.</param>
                /// <param name="oSizeROI">Region-of-Interest (ROI).</param>
                /// <param name="oCenter">center of circle that radial profile is computed from.  Center does not have to be on the image.</param>
                /// <param name="nAstigmatismRatio">ratio of orientation axis to orthogonal axis.  (i.e. 1.5 means stretched 1.5x)</param>
                /// <param name="nOrientationRadians">orientation of the astigmatism, clockwise in radians with 0.0 being vertical.</param>
                /// <param name="pProfileData">pointer to output NppiProfileData array containing count, mean, and std_dev as a function of radius.</param>
                /// <param name="nProfileSamples">number of radii to be sampled: from 0 through nProfileSamples-1.</param>
                /// <param name="nppStreamCtx">NPP stream context.</param>
                /// <returns></returns>
                [DllImport(NPPIST_API_DLL_NAME, CallingConvention = CallingConvention.Cdecl)]
                public static extern NppStatus nppiEllipticalRadialProfile_32f_C1R_Ctx(CUdeviceptr pSrc, int nSrcStep, NppiSize oSizeROI, NppiPoint32f oCenter,
                    float nAstigmatismRatio, float nOrientationRadians, CUdeviceptr pProfileData, ushort nProfileSamples, NppStreamContext nppStreamCtx);




            }

